package br.com.admeclesial.interfaces.rest.financeiro; import br.com.admeclesial.application.financeiro.*; import br.com.admeclesial.domain.financeiro.RegraRepasse; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/regras-repasse") public class RegraRepasseRestController { final RegraRepasseApplicationService s; public RegraRepasseRestController(RegraRepasseApplicationService s){this.s=s;} @PostMapping public RegraRepasse criar(@Valid @RequestBody RegraRepasseRequest r){return s.salvar(r);} @GetMapping public List<RegraRepasse> listar(){return s.listar();} }